(function() {
    'use strict';

    class LaunchLabAdapter extends USF.SimulationAdapter {
        constructor() {
            super();
            this.name = 'Launch Lab: Design the 4P Mix For Your Tribe';
            this.version = '1.1.0';

            // Five quarters. Rounds 1-4 are product launches with 4P decisions.
            // Round 5 is the portfolio-review synthesis.
            this.ROUNDS = [
                {
                    key: 'priya',
                    personaName: 'Priya',
                    personaTag: 'Premium Fitness Buyer',
                    personaAvatar: '💪',
                    personaQuote: 'If I am putting it in my body post-workout, I want to know every ingredient is earned.',
                    personaDescription: '34 years old. London. £65k income. CrossFit four times a week. Sustainability-minded. Reads labels. Trusts specialists over supermarkets.',
                    personaJTBD: 'Recover faster and fuel clean performance.',
                    productName: 'Plant-based Protein Powder',
                    productOptions: [
                        { label: 'Basic whey, artificial flavours, plastic tub', score: 0 },
                        { label: 'Standard whey, natural flavours', score: 1 },
                        { label: 'Premium plant blend, 25g protein, BCAAs', score: 2 },
                        { label: 'Organic plant-based, 30g protein, compostable packaging', score: 3 }
                    ],
                    priceOptions: [
                        { label: '£15 per tub — value tier', score: 0, unitPrice: 15 },
                        { label: '£28 per tub — mid tier', score: 1, unitPrice: 28 },
                        { label: '£38 per tub — premium tier', score: 2, unitPrice: 38 },
                        { label: '£52 per tub — luxury tier', score: 3, unitPrice: 52 }
                    ],
                    placeOptions: [
                        { label: 'Pound-shop and discount grocers', score: 0 },
                        { label: 'Amazon mass-market listing', score: 1 },
                        { label: 'Waitrose plus specialty gym-direct', score: 2 },
                        { label: 'Invite-only pop-ups and boutique fitness only', score: 3 }
                    ],
                    promotionOptions: [
                        { label: 'Daytime TV and press ads', score: 0 },
                        { label: 'Google Search and display performance ads', score: 1 },
                        { label: 'Instagram micro-influencers in CrossFit and wellness', score: 2 },
                        { label: 'Billboard plus elite-event sponsorships only', score: 3 }
                    ],
                    ideal: { product: 3, price: 2, place: 2, promotion: 2 },
                    unitCostByTier: [6, 10, 14, 18],
                    baseDemand: 2600,
                    minDemand: 120,
                    starThresholds: { consistency: 80, purchaseIntent: 60 }
                },
                {
                    key: 'greens',
                    personaName: 'The Greens',
                    personaTag: 'Eco-Conscious Family',
                    personaAvatar: '🌿',
                    personaQuote: 'We will pay a little more to do the right thing — but do not try to greenwash us.',
                    personaDescription: 'Chris and Sam, 40, two kids, Bristol. Eco-conscious middle income. Shop on Ocado and Tesco. Trust third-party certifications. Willing to pay ~15% premium, not 50%.',
                    personaJTBD: 'Clean the laundry without damaging the planet or the family budget.',
                    productName: 'Eco-Friendly Laundry Sheets',
                    productOptions: [
                        { label: 'Plastic-bottle liquid, no eco story', score: 0 },
                        { label: 'Recyclable plastic bottle, vague eco claims', score: 1 },
                        { label: 'Plastic-free sheets with third-party certifications', score: 2 },
                        { label: 'Luxe eco-concentrate, artisanal packaging, price doubled', score: 3 }
                    ],
                    priceOptions: [
                        { label: '15% below category average', score: 0, unitPrice: 6 },
                        { label: 'Category parity', score: 1, unitPrice: 8 },
                        { label: '~15% premium vs category', score: 2, unitPrice: 10 },
                        { label: '50% premium vs category', score: 3, unitPrice: 13 }
                    ],
                    placeOptions: [
                        { label: 'Discount retail only (Poundland, B&M)', score: 0 },
                        { label: 'Ocado plus Tesco plus Sainsburys', score: 1 },
                        { label: 'Specialty eco stores and health shops', score: 2 },
                        { label: 'DTC website only', score: 3 }
                    ],
                    promotionOptions: [
                        { label: 'Daytime TV mass-market ads', score: 0 },
                        { label: 'Digital and sustainability press with certification proof', score: 1 },
                        { label: 'Niche eco-influencers on Instagram', score: 2 },
                        { label: 'National newspaper print', score: 3 }
                    ],
                    ideal: { product: 2, price: 2, place: 1, promotion: 1 },
                    unitCostByTier: [3, 4, 5, 7],
                    baseDemand: 14000,
                    minDemand: 600,
                    starThresholds: { consistency: 70, purchaseIntent: 55 }
                },
                {
                    key: 'kai',
                    personaName: 'Kai',
                    personaTag: 'Gen-Z Phone-Native',
                    personaAvatar: '⚡',
                    personaQuote: 'If it feels like an ad, I am already scrolling past.',
                    personaDescription: '19 years old. Manchester. Uni student. Phone-native. Values authenticity. Suspicious of corporate marketing. Discovers brands on TikTok, buys on impulse in convenience stores.',
                    personaJTBD: 'Stay switched-on between lectures — and share something my group chat finds cool.',
                    productName: 'Gen-Z Energy Drink',
                    productOptions: [
                        { label: 'Classic cola clone', score: 0 },
                        { label: 'Standard sports isotonic', score: 1 },
                        { label: 'Bold flavour energy with Gen-Z brand codes', score: 2 },
                        { label: 'Nootropic premium, functional ingredients, boutique', score: 3 }
                    ],
                    priceOptions: [
                        { label: '£0.99 — below cost of branded drinks', score: 0, unitPrice: 0.99 },
                        { label: '£1.75 — impulse value', score: 1, unitPrice: 1.75 },
                        { label: '£2.50 — Gen-Z impulse ceiling', score: 2, unitPrice: 2.50 },
                        { label: '£3.50 — premium positioning', score: 3, unitPrice: 3.50 }
                    ],
                    placeOptions: [
                        { label: 'Supermarket pallets and petrol stations', score: 0 },
                        { label: 'Convenience stores plus student-union partnerships', score: 1 },
                        { label: 'Specialty health and vape shops', score: 2 },
                        { label: 'DTC subscription only', score: 3 }
                    ],
                    promotionOptions: [
                        { label: 'Daytime TV ads', score: 0 },
                        { label: 'Google Search performance ads', score: 1 },
                        { label: '70% TikTok creators plus user-generated content', score: 2 },
                        { label: 'National newspaper print ads', score: 3 }
                    ],
                    ideal: { product: 2, price: 2, place: 1, promotion: 2 },
                    unitCostByTier: [0.35, 0.55, 0.75, 1.10],
                    baseDemand: 90000,
                    minDemand: 3000,
                    starThresholds: { consistency: 70, brandFit: 75, authenticity: 70 }
                },
                {
                    key: 'timeshort',
                    personaName: 'Jess',
                    personaTag: 'Time-Poor Value Seeker',
                    personaAvatar: '⏱️',
                    personaQuote: 'Do not dress it up. Feed my kids, respect my time, respect my wallet.',
                    personaDescription: 'Jess, 39, two kids, full-time nurse. Budget-conscious. Does not care about gourmet. Cares about speed, reliability, and cost. Shops Tesco and Asda. Notices shelf price-tags more than ads.',
                    personaJTBD: 'Put dinner on the table in 20 minutes without overspending.',
                    productName: 'No-Frills Meal Kit',
                    productOptions: [
                        { label: 'Gourmet chef-designed kit, premium ingredients', score: 0 },
                        { label: 'Standard kit with balanced variety', score: 1 },
                        { label: 'Family basics — speed and value focused', score: 2 },
                        { label: 'Gluten-free niche kit', score: 3 }
                    ],
                    priceOptions: [
                        { label: '£2.99 per meal — aggressive value', score: 0, unitPrice: 2.99 },
                        { label: '£4.50 per meal — value tier', score: 1, unitPrice: 4.50 },
                        { label: '£7.99 per meal — mid tier', score: 2, unitPrice: 7.99 },
                        { label: '£12.99 per meal — premium gourmet', score: 3, unitPrice: 12.99 }
                    ],
                    placeOptions: [
                        { label: 'DTC subscription box only', score: 0 },
                        { label: 'Tesco plus Asda dominant retail', score: 1 },
                        { label: 'Farm shops and delis', score: 2 },
                        { label: 'Amazon Fresh only', score: 3 }
                    ],
                    promotionOptions: [
                        { label: 'In-store shelf-talkers and price-led ads', score: 0 },
                        { label: 'Facebook plus local mums groups', score: 1 },
                        { label: 'Lifestyle-influencer campaigns', score: 2 },
                        { label: 'TV brand-building sponsorship', score: 3 }
                    ],
                    ideal: { product: 2, price: 1, place: 1, promotion: 0 },
                    unitCostByTier: [1.10, 1.80, 3.00, 4.80],
                    baseDemand: 45000,
                    minDemand: 1800,
                    starThresholds: { consistency: 70, purchaseIntent: 55, margin: 12 }
                },
                {
                    key: 'portfolio',
                    personaName: 'Board Review',
                    personaTag: 'Portfolio Synthesis',
                    personaAvatar: '📊',
                    personaQuote: 'One launch lost us money. Tell us which, tell us why, and show us you understand segmentation.',
                    personaDescription: 'Four launches completed. The board is looking at the P&L of each and wants a diagnosis. Identify the weakest launch, its primary root cause, and prove you can classify tribes on the correct segmentation dimension.',
                    personaJTBD: 'Synthesise the quarter. Diagnose. Propose the next bet.',
                    productName: 'Portfolio Review'
                }
            ];
        }

        initialize(state) {
            if (!state.domainState || Object.keys(state.domainState).length === 0) {
                state.domainState = {
                    totalBrandFit: 0,
                    totalPurchaseIntent: 0,
                    totalSalesUnits: 0,
                    totalRevenue: 0,
                    totalProfit: 0,
                    totalStars: 0,
                    avgConsistency: 0,
                    brandFitHistory: [],
                    consistencyHistory: [],
                    purchaseIntentHistory: [],
                    salesHistory: [],
                    profitHistory: [],
                    starsHistory: [],
                    launches: []
                };
            }
            if (!state.decisions || Object.keys(state.decisions).length === 0) {
                state.decisions = {
                    productTier: 1,
                    priceTier: 1,
                    placeChannel: 1,
                    promotionMix: 1,
                    weakest: 0,
                    reason: 0,
                    dimension: 0
                };
            }
            this._updateBriefing(state);
        }

        _currentRound(state) {
            var period = state && state.currentPeriod ? state.currentPeriod : 1;
            var idx = Math.min(Math.max(period - 1, 0), this.ROUNDS.length - 1);
            return this.ROUNDS[idx];
        }

        _fillSelect(id, options, chosenIndex) {
            var el = document.getElementById(id);
            if (!el) return;
            el.innerHTML = '';
            for (var i = 0; i < options.length; i++) {
                var opt = document.createElement('option');
                opt.value = i;
                opt.textContent = options[i].label;
                if (i === chosenIndex) opt.selected = true;
                el.appendChild(opt);
            }
        }

        _updateBriefing(state) {
            var round = this._currentRound(state);
            var isPortfolio = round.key === 'portfolio';
            var _dec = state.decisions || {};

            var nameEl = document.getElementById('personaName');
            if (nameEl) nameEl.textContent = round.personaName;
            var tagEl = document.getElementById('personaTag');
            if (tagEl) tagEl.textContent = round.personaTag;
            var avatarEl = document.getElementById('personaAvatar');
            if (avatarEl) avatarEl.textContent = round.personaAvatar;
            var quoteEl = document.getElementById('personaQuote');
