            // Persist a normalized 0-100 score (stars out of the 15 max) so the
            // grading/reporting layer can read domainState.performance.overallScore.
            var _sc = this._score(state.domainState.totalStars);
            state.domainState.score = _sc;
            state.domainState.performance = { overallScore: _sc, grade: this._grade(_sc) };
