        _calculateLaunchResults(state, round) {
            var d = state.decisions;
            var ideal = round.ideal;

            var productDelta   = Math.abs(d.productTier   - ideal.product);
            var priceDelta     = Math.abs(d.priceTier     - ideal.price);
            var placeDelta     = Math.abs(d.placeChannel  - ideal.place);
            var promotionDelta = Math.abs(d.promotionMix  - ideal.promotion);

            var productScore   = Math.max(0, 100 - productDelta   * 28);
            var priceScore     = Math.max(0, 100 - priceDelta     * 32);
            var placeScore     = Math.max(0, 100 - placeDelta     * 26);
            var promotionScore = Math.max(0, 100 - promotionDelta * 26);

            var brandFit = Math.round((productScore + priceScore + placeScore + promotionScore) / 4);

            // Mix consistency = how tightly the 4 choices cluster around the same tier.
            var values = [d.productTier, d.priceTier, d.placeChannel, d.promotionMix];
            var mean = (values[0] + values[1] + values[2] + values[3]) / 4;
            var variance = 0;
            for (var i = 0; i < 4; i++) variance += (values[i] - mean) * (values[i] - mean);
            variance = variance / 4;
            var consistency = Math.max(0, Math.round(100 - variance * 35));

            // Purchase intent is weighted toward price match and product fit
            var purchaseIntent = Math.round(priceScore * 0.45 + productScore * 0.30 + promotionScore * 0.15 + placeScore * 0.10);

            // Message recall and authenticity
            var messageRecall = Math.round(promotionScore * 0.65 + placeScore * 0.35);
            var authenticity  = Math.round((productScore + promotionScore) / 2);

            // Sales forecast and margin
            var demandFactor = (brandFit / 100) * (purchaseIntent / 100);
            var priceIdx = Math.max(0, Math.min(3, d.priceTier));
            var priceTierMix = [1.5, 1.15, 0.85, 0.55][priceIdx];
            var salesUnits = Math.max(round.minDemand, Math.round(round.baseDemand * demandFactor * priceTierMix));

            var unitPrice = round.priceOptions[priceIdx].unitPrice;
            var unitCost  = round.unitCostByTier[Math.max(0, Math.min(3, d.productTier))];
            var revenue = salesUnits * unitPrice;
            var costs   = salesUnits * unitCost;
            var profit  = Math.round(revenue - costs);
            var marginPct = revenue > 0 ? Math.round((profit / revenue) * 100) : 0;

            // Stars — follow the concept star triggers per round
            var stars = 1; // completed the round
            if (round.key === 'priya' && consistency >= 80 && purchaseIntent >= 60) stars = 2;
            if (round.key === 'greens' && consistency >= 70 && marginPct >= 15 && brandFit >= 70) stars = 2;
            if (round.key === 'kai' && brandFit >= 75 && authenticity >= 70) stars = 2;
            if (round.key === 'timeshort' && purchaseIntent >= 55 && marginPct >= 12 && brandFit >= 70) stars = 2;
            if (profit > 0 && consistency >= 80 && brandFit >= 80) stars = 3;

            // Update cumulative domain state
            state.domainState.totalBrandFit += brandFit;
            state.domainState.totalPurchaseIntent += purchaseIntent;
            state.domainState.totalSalesUnits += salesUnits;
            state.domainState.totalRevenue += revenue;
            state.domainState.totalProfit += profit;
            state.domainState.totalStars += stars;
            state.domainState.avgConsistency = Math.round(
                (state.domainState.avgConsistency * state.domainState.launches.length + consistency) /
                (state.domainState.launches.length + 1)
            );

            var launchRecord = {
                key: round.key,
                personaName: round.personaName,
                productName: round.productName,
                brandFit: brandFit,
                consistency: consistency,
                purchaseIntent: purchaseIntent,
                messageRecall: messageRecall,
                salesUnits: salesUnits,
                revenue: revenue,
                profit: profit,
                marginPct: marginPct,
                stars: stars,
                decisions: {
                    product: round.productOptions[d.productTier].label,
                    price: round.priceOptions[d.priceTier].label,
                    place: round.placeOptions[d.placeChannel].label,
                    promotion: round.promotionOptions[d.promotionMix].label
                }
            };
            state.domainState.launches.push(launchRecord);

            return {
                period: state.currentPeriod,
                brandFit: brandFit,
                consistency: consistency,
                purchaseIntent: purchaseIntent,
                messageRecall: messageRecall,
                authenticity: authenticity,
                salesUnits: salesUnits,
                revenue: revenue,
                profit: profit,
                marginPct: marginPct,
                starsEarned: stars,
                personaName: round.personaName,
                productName: round.productName,
                weakestCorrect: null,
                reasonCorrect: null,
                dimensionCorrect: null
            };
        }

        _calculatePortfolioResults(state) {
            var launches = state.domainState.launches || [];
            // Weakest = lowest profit
            var weakestIdx = 0;
            var weakestProfit = Number.POSITIVE_INFINITY;
            for (var i = 0; i < launches.length; i++) {
                if (launches[i].profit < weakestProfit) {
                    weakestProfit = launches[i].profit;
                    weakestIdx = i;
                }
            }

            // Reason inferred from which delta was biggest in the weakest launch vs ideal
            var worstRound = this.ROUNDS[weakestIdx];
            var launchRec = launches[weakestIdx];
            var reasonIdx = 0; // default mis-positioning
            if (worstRound && worstRound.ideal) {
                var deltas = [
                    0,
                    0,
                    0,
                    0
                ];
                // Rebuild player-chosen tiers from record labels is brittle; instead, rely on stored history record
                var hist = (window.mySimulation && window.mySimulation.state && window.mySimulation.state.history) || [];
                if (hist[weakestIdx] && hist[weakestIdx].decisions) {
                    var hd = hist[weakestIdx].decisions;
                    deltas[0] = Math.abs((hd.productTier || 0) - worstRound.ideal.product);     // positioning
                    deltas[1] = Math.abs((hd.priceTier || 0) - worstRound.ideal.price);         // price
                    deltas[2] = Math.abs((hd.placeChannel || 0) - worstRound.ideal.place);      // channel
                    deltas[3] = Math.abs((hd.promotionMix || 0) - worstRound.ideal.promotion);  // promotion
                    var maxDelta = deltas[0];
                    reasonIdx = 0;
                    for (var j = 1; j < 4; j++) {
                        if (deltas[j] > maxDelta) { maxDelta = deltas[j]; reasonIdx = j; }
                    }
                }
            }

            // Kai is primarily psychographic / generational — coded as psychographic = 2
            var correctDimension = 2;

            var d = state.decisions;
            var weakestCorrect = (d.weakest === weakestIdx);
            var reasonCorrect  = (d.reason === reasonIdx);
            var dimensionCorrect = (d.dimension === correctDimension);

            var diagScore = 0;
            if (weakestCorrect) diagScore += 40;
            if (reasonCorrect)  diagScore += 40;
            if (dimensionCorrect) diagScore += 20;

            var stars = 1;
            if (diagScore >= 80) stars = 2;
            if (diagScore === 100) stars = 3;

            state.domainState.totalStars += stars;

            return {
                period: state.currentPeriod,
                brandFit: diagScore,
                consistency: diagScore,
                purchaseIntent: 0,
                messageRecall: 0,
                authenticity: 0,
                salesUnits: 0,
                revenue: 0,
                profit: 0,
                marginPct: 0,
                starsEarned: stars,
                personaName: 'Board Review',
                productName: 'Portfolio Synthesis',
                diagnosticScore: diagScore,
                weakestCorrect: weakestCorrect,
                reasonCorrect: reasonCorrect,
                dimensionCorrect: dimensionCorrect,
                correctWeakestLabel: (this.ROUNDS[weakestIdx] && this.ROUNDS[weakestIdx].personaName) || '',
                correctReasonIndex: reasonIdx
            };
        }

